CREATE TABLE "new__marketplace_listing" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "currency" varchar(3) NOT NULL, "slug" varchar(180) NOT NULL UNIQUE, "description" text NOT NULL, "price_cents" integer unsigned NOT NULL CHECK ("price_cents" >= 0), "published" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" bigint NOT NULL REFERENCES "marketplace_category" ("id") DEFERRABLE INITIALLY DEFERRED, "game_id" bigint NOT NULL UNIQUE REFERENCES "games_game" ("id") DEFERRABLE INITIALLY DEFERRED, "seller_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
INSERT INTO "new__marketplace_listing" ("id", "slug", "description", "price_cents", "published", "created_at", "updated_at", "category_id", "game_id", "seller_id", "currency") SELECT "id", "slug", "description", "price_cents", "published", "created_at", "updated_at", "category_id", "game_id", "seller_id", "currency" FROM "marketplace_listing";
DROP TABLE "marketplace_listing";
ALTER TABLE "new__marketplace_listing" RENAME TO "marketplace_listing";
CREATE INDEX "marketplace_listing_category_id_cab5ec78" ON "marketplace_listing" ("category_id");
CREATE INDEX "marketplace_listing_seller_id_56a0f16d" ON "marketplace_listing" ("seller_id");
CREATE TABLE "new__marketplace_payout" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "amount_cents" integer unsigned NOT NULL CHECK ("amount_cents" >= 0), "reversed_cents" integer unsigned NOT NULL CHECK ("reversed_cents" >= 0), "status" varchar(16) NOT NULL, "stripe_transfer_id" varchar(255) NOT NULL UNIQUE, "idempotency_key" varchar(255) NOT NULL UNIQUE, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "creator_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "currency" varchar(3) NOT NULL);
INSERT INTO "new__marketplace_payout" ("id", "amount_cents", "reversed_cents", "status", "stripe_transfer_id", "idempotency_key", "created_at", "updated_at", "creator_id", "currency") SELECT "id", "amount_cents", "reversed_cents", "status", "stripe_transfer_id", "idempotency_key", "created_at", "updated_at", "creator_id", "currency" FROM "marketplace_payout";
DROP TABLE "marketplace_payout";
ALTER TABLE "new__marketplace_payout" RENAME TO "marketplace_payout";
CREATE INDEX "marketplace_payout_creator_id_6a20c109" ON "marketplace_payout" ("creator_id");
CREATE TABLE "new__marketplace_purchase" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(160) NOT NULL, "price_cents" integer unsigned NOT NULL CHECK ("price_cents" >= 0), "platform_fee_cents" integer unsigned NOT NULL CHECK ("platform_fee_cents" >= 0), "processing_estimate_cents" integer unsigned NOT NULL CHECK ("processing_estimate_cents" >= 0), "creator_credit_cents" integer unsigned NOT NULL CHECK ("creator_credit_cents" >= 0), "refunded_cents" integer unsigned NOT NULL CHECK ("refunded_cents" >= 0), "disputed_cents" integer unsigned NOT NULL CHECK ("disputed_cents" >= 0), "status" varchar(16) NOT NULL, "stripe_checkout_session_id" varchar(255) NOT NULL, "stripe_payment_intent_id" varchar(255) NOT NULL, "stripe_charge_id" varchar(255) NOT NULL, "paid_at" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "buyer_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "game_id" bigint NULL REFERENCES "games_game" ("id") DEFERRABLE INITIALLY DEFERRED, "listing_id" bigint NULL REFERENCES "marketplace_listing" ("id") DEFERRABLE INITIALLY DEFERRED, "seller_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "currency" varchar(3) NOT NULL);
INSERT INTO "new__marketplace_purchase" ("id", "title", "price_cents", "platform_fee_cents", "processing_estimate_cents", "creator_credit_cents", "refunded_cents", "disputed_cents", "status", "stripe_checkout_session_id", "stripe_payment_intent_id", "stripe_charge_id", "paid_at", "created_at", "updated_at", "buyer_id", "game_id", "listing_id", "seller_id", "currency") SELECT "id", "title", "price_cents", "platform_fee_cents", "processing_estimate_cents", "creator_credit_cents", "refunded_cents", "disputed_cents", "status", "stripe_checkout_session_id", "stripe_payment_intent_id", "stripe_charge_id", "paid_at", "created_at", "updated_at", "buyer_id", "game_id", "listing_id", "seller_id", "currency" FROM "marketplace_purchase";
DROP TABLE "marketplace_purchase";
ALTER TABLE "new__marketplace_purchase" RENAME TO "marketplace_purchase";
CREATE UNIQUE INDEX "uniq_marketplace_purchase_per_game" ON "marketplace_purchase" ("buyer_id", "game_id") WHERE "status" IN ('pending', 'paid', 'refunded', 'disputed');
